mapper.select:
SELECT e.EMP_ID AS empId, e.EMP_NAME AS empName, e.EMAIL AS email, e.DEPT_ID AS deptId, e.JOB_CODE AS jobCode, e.SALARY AS salary, e.HIRE_DATE AS hireDate, e.PHONE AS phone, e.ENT_YN AS entYn FROM emp e
ORDER BY ${sort.column} ${sort.direction}
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE emp
SET EMP_NAME = #{empName},
    EMAIL = #{email}
WHERE EMP_ID = #{empId}
